// The native shell's protocol, both ends generated by `tool/prepare.sh`: what
// the app (the server, holding every rule and all the state) tells a client
// to draw, a concern's whole state at a time and only when it changed, and
// what the client says the user did. See "Liquid Glass" in lib/ui/AGENTS.md.

// Pigeon's style: a field with no default is declared bare, and Pigeon makes
// it a required parameter of the class it generates. This file is read by
// Pigeon, never compiled, so the one thing the analyzer would say of that is
// set aside and everything else is checked.
// ignore_for_file: not_initialized_non_nullable_instance_field

import "package:pigeon/pigeon.dart";

@ConfigurePigeon(
  PigeonOptions(
    dartPackageName: "entoli_glass",
    dartOut: "packages/entoli_glass/lib/src/shell_contract.g.dart",
    dartTestOut: "test/ui/shell/native_shell.g.dart",
    swiftOut:
        "packages/entoli_glass/darwin/entoli_glass/Sources/entoli_glass/Contract/ShellContract.g.swift",
  ),
)
/// What an icon stands for, never how it is drawn: the client picks its own
/// picture for each, in an exhaustive switch.
enum Glyph {
  add,
  check,
  checklist,
  close,
  copy,
  newFolder,
  delete,
  edit,
  filter,
  textSize,
  openInBrowser,
  openExternal,
  restart,
  save,
  show,
  hidden,
  more,
  terminal,
  globe,
  browse,
  document,
  shield,
  home,
  folder,
  team,
  remote,
  info,
  tune,
}

/// The window around everything: whether the sidebar is shown, and which
/// appearance the app wears, which may not be the system's.
class WindowSnapshot {
  bool sidebarShown;

  /// Whether the app is dark; null for the system's appearance.
  bool? dark;
}

/// A project as the switcher lists it, and as a chat's Move offers it.
/// [device] and [project] are its `ProjectRef`, which an intent hands back.
class ProjectChoice {
  ProjectChoice({
    this.device,
    this.project,
    required this.label,
    this.glyph,
    this.omada = false,
    this.count = 0,
  });

  String? device;
  String? project;
  String label;

  /// Null for none.
  Glyph? glyph;

  /// Drawn italic, as the Flutter app draws an Omada project's name.
  bool omada;
  int count;
}

/// One chat's row.
class SidebarRow {
  SidebarRow({
    required this.id,
    required this.title,
    this.pinned = false,
    this.busy = false,
    this.temporary = false,
    this.offline = false,
    this.mutable = true,
    this.remote = false,
  });

  String id;

  /// Empty for a chat not named yet.
  String title;
  bool pinned;

  /// A turn runs in it, or its browser tab is open.
  bool busy;

  /// It will expire: the hourglass.
  bool temporary;

  /// A mirror whose home device is away.
  bool offline;

  /// Its menu is on offer: false for a mirror whose device is away.
  bool mutable;

  /// A mirror, whose projects are its home device's, so it has no Move.
  bool remote;
}

/// The rows under one heading; a paired device's list is one group with no
/// heading, a mirror answering to no date this sidebar could place it under.
/// How long ago a group's chats last changed, or that they are pinned; the
/// client words the heading.
enum ChatPeriod {
  pinned,
  today,
  yesterday,
  previousWeek,
  previousMonth,
  month,
  none,
}

class SidebarGroup {
  SidebarGroup({required this.period, this.month, this.rows = const []});

  /// [ChatPeriod.none] for a list with no headings: a paired device's.
  ChatPeriod period;

  /// For [ChatPeriod.month], its first day, in milliseconds since the epoch.
  int? month;
  List<SidebarRow> rows;
}

/// Why the sidebar has no rows.
enum SidebarEmpty { noChats, noMirrored, noMatch }

/// A page the app opens over the conversation from the shell's chrome.
enum ShellPage {
  workspace,
  memories,
  projectSettings,
  settings,
  profile,
  marketplace,
}

/// The sidebar: the project being shown and the pages it has beside its
/// chats, its chats under their headings as the search leaves them, and every
/// project for the switcher.
class SidebarSnapshot {
  SidebarSnapshot({
    required this.project,
    this.pages = const [],
    this.groups = const [],
    this.selected,
    this.query = "",
    this.empty,
    this.projects = const [],
    this.devices = const [],
    this.omadaByDefault = false,
  });

  ProjectChoice project;

  /// Of the project's own pages, the ones it has.
  List<ShellPage> pages;
  List<SidebarGroup> groups;
  String? selected;

  /// What the search field holds: the app's, so switching project clears it.
  String query;

  /// Why there are no rows, null where there are.
  SidebarEmpty? empty;

  /// This device's projects, the default and the built-ins first: the
  /// switcher's, and where a local chat can be moved to.
  List<ProjectChoice> projects;

  /// The paired devices' projects.
  List<ProjectChoice> devices;

  /// What the new-project sheet's Omada switch starts at.
  bool omadaByDefault;
}

/// How a [TitleBarItem] is drawn: an icon, a word, a word in the accent's
/// fill, or the page's tick — the system's confirm, where it has one.
enum TitleBarItemStyle { icon, text, prominent, confirm }

/// One choice of a [TitleBarItem] that opens a menu.
class TitleBarMenuItem {
  TitleBarMenuItem({
    required this.id,
    required this.label,
    this.hint,
    this.glyph,
    this.checked = false,
  });

  /// What a pick sends back, as a press's `id`.
  String id;
  String label;

  /// Drawn after the label, quieter: a key or a trigger.
  String? hint;

  /// Drawn before the label.
  Glyph? glyph;

  /// Ticked, as a setting the choice turns on and off.
  bool checked;
}

/// A button of a title bar, or its spinner.
class TitleBarItem {
  TitleBarItem({
    required this.id,
    required this.label,
    this.glyph,
    this.spinner = false,
    this.style = TitleBarItemStyle.icon,
    this.enabled = true,
    this.menu = const [],
  });

  /// What a press sends back, as [TitleBarIntents.press]'s `id`.
  String id;

  /// Its tooltip and accessibility label, and the word a text one shows.
  String label;

  /// None for the spinner, and for an item the client words instead.
  Glyph? glyph;
  bool spinner;
  TitleBarItemStyle style;
  bool enabled;

  /// Its choices, where it opens a menu rather than doing one thing.
  List<TitleBarMenuItem> menu;
}

/// What leads a title bar where something does: a way back, or a close that
/// discards.
enum TitleBarLeading { back, close }

/// A title bar, as one view draws them all: the chat's, which the client
/// builds from [ChatBarSnapshot].
class TitleBarSnapshot {
  TitleBarSnapshot({
    this.present = true,
    required this.title,
    this.subtitle = "",
    this.expiresAt,
    this.leading,
    this.items = const [],
  });

  /// False where there is no bar to draw: the window keeps the chat's title.
  bool present;
  String title;
  String subtitle;

  /// When a temporary chat expires, in milliseconds since the epoch; the
  /// client counts down to it.
  int? expiresAt;
  TitleBarLeading? leading;
  List<TitleBarItem> items;
}

/// The chat's title bar, as the chat's state: the client draws its own bar
/// from it, its own buttons and words.
class ChatBarSnapshot {
  ChatBarSnapshot({
    this.title = "",
    this.draft = false,
    this.project,
    this.pinned = false,
    this.expiresAt,
    this.running = false,
    this.planDone,
    this.planTotal,
    this.settings = true,
  });

  /// Empty for a chat not named yet.
  String title;

  /// The new-chat screen's, there being no chat yet.
  bool draft;

  /// The project's label, null for the default project.
  String? project;
  bool pinned;

  /// When a temporary chat expires, in milliseconds since the epoch.
  int? expiresAt;
  bool running;

  /// The plan's sections done and in all, where the chat has a plan.
  int? planDone;
  int? planTotal;

  /// Whether its settings can be opened: not a paired device's new chat.
  bool settings;
}

/// Where the chat's bar can take the app.
enum ChatBarDestination { plan, settings }

/// A pending file.
class ComposerAttachment {
  String name;
  bool image;
}

/// One entry of the composer's `/` or `@` menu.
class ComposerMenuItem {
  /// The skill's or the agent's name, without its trigger.
  String name;

  /// Which menu it is in: an agent's row leads with its face.
  ComposerTrigger trigger;
  String? hint;
  String? detail;

  /// An agent's face as a PNG, a still drawn by Flutter; null for a skill,
  /// and for an agent with no face to show, which the row draws as a person.
  Uint8List? picture;
}

/// What an embed in the field draws as.
class ComposerCard {
  String? title;
  String body;
}

/// What the field is for: a message, a `!` command run on the machine, or an
/// answer to a callback.
enum InputMode { message, shell, callback }

/// Everything the native composer draws apart from its text, which is
/// [ComposerValueSnapshot]. Not [present] where no page has a composer: a
/// question stands in its place, or the project needs setting up.
/// Which callback the field holds, for the client to name: the core says
/// what it is, never what to call it.
enum CallbackKind {
  compact,
  setGoal,
  resumeGoal,
  pauseGoal,
  clearGoal,
  showGoal,
}

class ComposerSnapshot {
  ComposerSnapshot({
    required this.present,
    this.mode = InputMode.message,
    this.callback,
    this.canSend = false,
    this.queues = false,
    this.speaking = false,
    this.voice = false,
    this.attachments = const [],
    this.menu = const [],
    this.cwd,
    this.cards = const {},
  });

  bool present;

  InputMode mode;

  /// In [InputMode.callback], which one.
  CallbackKind? callback;
  bool canSend;

  /// What is typed would steer the running turn, so Queue is on offer.
  bool queues;

  /// A turn is running: an empty field's button is Stop.
  bool speaking;

  /// Voice mode can be opened from here.
  bool voice;
  List<ComposerAttachment> attachments;

  /// The open completion menu, empty for none.
  List<ComposerMenuItem> menu;

  /// Where a `!` command will run, for shell mode's row.
  String? cwd;

  /// The embeds in the field, by the UTF-16 code unit standing for each.
  Map<int, ComposerCard> cards;
}

/// The composer's text and selection, in UTF-16 code units, sent when the app
/// changed them: a completion taken, a message restored, the field cleared on
/// send. [revision] counts those, so a value the same as one the user typed
/// is still a change; what the user typed is never sent back to them.
class ComposerValueSnapshot {
  String text;
  int start;
  int end;
  int revision;
}

/// One thing the chat has running: a pill, standing alone or in its group.
/// What a chat has running beside the reply.
enum RunningKind { browser, job, subAgent }

/// One thing the chat has running: what it is and its name, the client
/// wording the pill, its group and its tooltip.
class RunningSnapshot {
  RunningSnapshot({
    required this.id,
    required this.kind,
    required this.name,
    this.hidden = false,
  });

  /// What [TurnIntents.running] names it by.
  int id;
  RunningKind kind;

  /// The browser page's host, the job's command, the sub-agent's name.
  String name;

  /// The browser is hidden from the agent.
  bool hidden;
}

/// A say the turn has not read yet: its id and its one line.
class SteerSnapshot {
  String id;

  /// What was said, and the files it carried.
  String text;
  List<String> files;
}

/// A call the turn stopped on, and which answers it offers.
class ApprovalSnapshot {
  ApprovalSnapshot({
    required this.id,
    required this.title,
    required this.glyph,
    required this.tool,
    this.detail,
    this.allow = true,
    this.chat = false,
    this.project = false,
  });

  String id;
  String title;
  Glyph glyph;
  String tool;

  /// The call as the agent worded it, verbatim.
  String? detail;

  /// Allow, Always in chat and Always in project, where each is on offer;
  /// Deny always is.
  bool allow;
  bool chat;
  bool project;
}

/// One option of a question.
class QuestionOption {
  String label;
  String? detail;

  /// What picking it answers.
  String answer;
}

/// One question the turn asks.
class QuestionSnapshot {
  String question;
  String? summary;
  List<QuestionOption> options;
}

/// What the turn is waiting to be told: the request's id and its questions.
class QuestionRequest {
  String id;
  List<QuestionSnapshot> questions;
}

/// Where a chat's goal stands: `GoalStatus` in the domain.
enum GoalPhase { active, paused, met, blocked }

/// Why a project could not be made: the name was not one, or the making
/// failed.
enum ProjectError { badName, failed }

/// The chat's goal, the row above the composer while there is one.
class GoalSnapshot {
  String objective;
  GoalPhase phase;

  /// Why it stands where it does: the user's pause, the reviewer's verdict.
  String? reason;
}

/// An unfinished turn the resume bar offers to carry on.
class ResumeSnapshot {
  /// When it started, in milliseconds since the epoch.
  int startedAt;

  /// What the backend said of it, where it said something.
  String? notice;
}

/// What a running turn puts above the composer: the offer to carry on an
/// interrupted one, the chat's goal, what is running, what was said to it
/// unread, and the calls waiting on an answer. Empty where no chat page has
/// one.
class TurnSnapshot {
  TurnSnapshot({
    this.goal,
    this.resume,
    this.running = const [],
    this.steers = const [],
    this.withdrawable = false,
    this.approvals = const [],
    this.question,
  });

  /// The chat's goal, null for none.
  GoalSnapshot? goal;

  /// The unfinished turn to carry on, null for none.
  ResumeSnapshot? resume;
  List<RunningSnapshot> running;
  List<SteerSnapshot> steers;

  /// A say can be taken back into the composer.
  bool withdrawable;
  List<ApprovalSnapshot> approvals;

  /// What the turn is waiting to be told, in the composer's place. The client
  /// holds what is picked until Send, as the Flutter panel does.
  QuestionRequest? question;
}

/// A paired device's name, whether it is away, and its projects.
class DeviceSnapshot {
  String name;
  bool offline;
  List<ProjectChoice> projects;
}

/// A project picked out, as a [ProjectChoice]'s device and project.
class ProjectPick {
  String? device;
  String? project;
}

/// A starter: a `/skill` or `@agent` the library holds.
class StarterSnapshot {
  ComposerTrigger trigger;
  String name;
  String? detail;
}

/// The new-chat screen: the question, the projects as badges — this device's,
/// then each paired device's under its name — with the one the next chat
/// goes to picked out, and a starter per `/skill` and `@agent` the library
/// holds. Not [present] where no page is the new-chat screen.
class NewChatSnapshot {
  NewChatSnapshot({
    required this.present,
    this.question = "",
    this.image,
    this.projects = const [],
    this.devices = const [],
    this.selected,
    this.starters = const [],
    this.showStarters = false,
    this.starting = false,
  });

  bool present;

  /// What the screen asks; empty asks nothing.
  String question;

  /// The figure over the question, as a Flutter asset key the client finds in
  /// the app's bundle.
  String? image;

  /// This device's projects that have a badge: every one but the default,
  /// which is nothing picked.
  List<ProjectChoice> projects;
  List<DeviceSnapshot> devices;
  ProjectPick? selected;
  List<StarterSnapshot> starters;

  /// Whether [starters] is drawn at all: the "Show command chips in start
  /// page" switch, which is off by default. Sent rather than left to the
  /// client to empty, because an empty library and a hidden row are two
  /// different screens — one says how to reach the library, the other says
  /// nothing.
  bool showStarters;

  /// A paired device is making the chat: a spinner in the screen's place.
  bool starting;
}

/// Who a line of the transcript is: the user, the reply, or what the turn
/// did.
enum VoiceLineRole { said, replied, activity }

/// One line of the transcript.
class VoiceLineSnapshot {
  VoiceLineRole kind;
  String text;
}

/// What voice mode is doing.
enum VoicePhase { off, starting, listening, thinking, speaking, failed }

/// Voice mode, drawn over the whole window: the session's status and its
/// word, whether the microphone is shut and what shut means, what went wrong,
/// the chat's title and what has been said. The microphone's level goes on
/// its own, many times a second, as [NativeShell.voiceLevel].
class VoiceSnapshot {
  VoiceSnapshot({
    required this.present,
    this.title,
    this.status = VoicePhase.off,
    this.paused = false,
    this.hushed = false,
    this.pushToTalk = false,
    this.on = false,
    this.error,
    this.lines = const [],
  });

  bool present;

  /// The chat's title; null for one not named yet.
  String? title;

  VoicePhase status;
  bool paused;

  /// Shut and silent: the one look that is the state's rather than the
  /// status's.
  bool hushed;
  bool pushToTalk;

  /// The session is running: the microphone's button does something.
  bool on;
  String? error;

  /// The transcript's last lines.
  List<VoiceLineSnapshot> lines;
}

/// One row of the palette: a project to switch to, or a chat to open.
class PaletteItem {
